def list_():
    """
    List the RAID devices.

    CLI Example:

    .. code-block:: bash

        salt '*' raid.list
    """
    ret = {}
    for raid in __salt__["raid.list_"]():
        ret[raid] = {}
        for disk in __salt__["raid.list_disks"](raid):
            ret[raid][disk] = {}
            for partition in __salt__["raid.list_partitions"](raid, disk):
                ret[raid][disk][partition] = {}
                for volume in __salt__["raid.list_volumes"](raid, disk, partition):
                    ret[raid][disk][partition][volume] = {}
                    for level in __salt__["raid.list_levels"](raid, disk, partition, volume):
                        ret[raid][disk][partition][volume][level] = {}
                        for member in __salt__["raid.list_members"](raid, disk, partition, volume, level):
                            ret[raid][disk][partition][volume][level][member] = {}
                            for status in __salt__["raid.list_status"](raid, disk, partition, volume, level, member):
                                ret[raid][disk][partition][volume][level][member][status] = {}
                                for attribute in __salt__["raid.list_attributes"](
                                    raid, disk, partition, volume, level, member, status
                                ):
                                    ret[raid][disk][partition][volume][level][member][status][attribute] = {}
                                    for value in __salt__["raid.list_values"](
                                        raid, disk, partition, volume, level, member, status, attribute
                                    ):
                                        ret[raid][disk][partition][volume][level][member][status][attribute][value] = {}
    return ret

